import {survivalCondition} from './survival-health.js';
import {memberSurvivalCareOptions,survivalPackItems} from './survival-pack.js';
import {survivalMemberName} from './survival-base.js';
const healthEsc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderMemberHealth(state,member,care=true){
 const c=survivalCondition(member),options=care?memberSurvivalCareOptions(state,member.key):[];
 return `<section class="survival-health-card" data-health-member="${member.key}"><header><strong>${healthEsc(survivalMemberName(state,member))}</strong><span>${c.critical?'치료 우선':c.warning.length?'회복 필요':'활동 가능'}</span></header><div class="health-meters"><label>포만감 <b>${c.nutrition}/100</b><meter min="0" max="100" low="35" high="60" optimum="80" value="${c.nutrition}"></meter></label><label>수분 <b>${c.hydration}/100</b><meter min="0" max="100" low="35" high="60" optimum="80" value="${c.hydration}"></meter></label></div>${c.dryNights||c.starveNights?`<p class="health-warning">수분 바닥 ${c.dryNights}밤 · 포만감 바닥 ${c.starveNights}밤<br>수분 0이 3밤 / 포만감 0이 5밤 이어지면 생존이 위험해요.</p>`:''}<p>피로 ${member.fatigue} · 부담 ${member.stress}<br>예상 원정 스태미나 ${c.stamina} / 회복 상한 ${c.staminaCap} · 공포 ${c.fear}</p>${member.injury>0?`<p class="health-wound ${c.woundRisk>=50?'wound-danger':''}">상처 ${member.injury} · ${c.caredDay===state.survivalRun.day?'오늘 치료함':'방치 '+c.woundDays+'일'}<br>악화 위험 ${c.woundRisk}/100${c.woundRisk>=80?' · 원정과 작업 불가':''}</p>`:'<p class="health-wound">열린 상처 없음</p>'}${c.warning.length?`<p class="health-warning">${c.warning.join(' · ')} · 먹고 마시거나 치료해야 해요.</p>`:''}${care?`<div class="health-care-actions">${options.map(o=>`<button data-action="survivalMemberCare" data-value="${member.key}:${o.action}" ${o.blocked?'disabled':''}>${({food:'먹기',water:'물 마시기',treat:'상처 치료'})[o.action]}<small>${o.id?survivalPackItems[o.id].name+' 1 · '+(o.source==='bag'?'가방':'보관 물자'):'사용할 물품 없음'}${o.action==='treat'?' · 여력 1':''}</small></button>`).join('')}</div>`:''}</section>`;
}
export function renderSurvivalVitals(state){return `<section class="survival-vitals" aria-label="원정 인원 몸 상태">${state.survivalRun.members.filter(m=>['taei','ally'].includes(m.key)).map(m=>renderMemberHealth(state,m)).join('')}</section>`;}
